using System.ComponentModel;using System.Drawing;using System.Drawing.Design;namespace LessonEditor.components {    internal class GradientPropertyEditor : UITypeEditor {        public override bool GetPaintValueSupported(ITypeDescriptorContext context) {            return true;        }        public override void PaintValue(PaintValueEventArgs e) {            var sample = e.Value as GradientProperty;            if (sample != null) {                int x = e.Bounds.X, y = e.Bounds.Y;                int w = e.Bounds.Width, h = e.Bounds.Height;                using (var b = new SolidBrush(sample.Color1))                    e.Graphics.FillRectangle(b, x, y, w / 3, h);                using (var b = new SolidBrush(sample.Color2))                    e.Graphics.FillRectangle(b, x += w / 3, y, w / 3, h);                using (var b = new SolidBrush(sample.Color3))                    e.Graphics.FillRectangle(b, x += w / 3, y, w / 3 + 1, h);            }            base.PaintValue(e);        }    }    [TypeConverter(typeof(ExpandableObjectConverter))]    [Editor(typeof(GradientPropertyEditor), typeof(UITypeEditor))]    public class GradientProperty {        public Color Color1 { get; set; } = Color.Red;        public Color Color2 { get; set; } = Color.Green;        public Color Color3 { get; set; } = Color.Blue;    }}// implement        [CategoryAttribute("VYPLNIT A VYTÁHNOUT"),            PropertyOrder(1),            DisplayName("Gradient výplně"),            DescriptionAttribute("Gradient výplně")        ]        [Editor(typeof(GradientPropertyEditor), typeof(UITypeEditor))] // specify editor for the property        GradientProperty FillGradient { get; set; }        public GradientProperty FillGradient { get; set; } = new GradientProperty();